import cgi
import http.server
import json

SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}

class PostHandler(http.server.BaseHTTPRequestHandler):
    def do_POST(self):
        # Check Content-Type header
        content_type = self.headers.get('Content-Type', '')
        if 'application/json' not in content_type:
            self.send_error_response(400, "Content-Type header is not application/json")
            return

        # Get content length
        try:
            content_length = int(self.headers['Content-Length'])
        except (KeyError, ValueError):
            self.send_error_response(400, "Missing or invalid Content-Length header")
            return

        # Read the request body
        try:
            post_data = self.rfile.read(content_length)
            data = json.loads(post_data.decode('utf-8'))
        except json.JSONDecodeError:
            self.send_error_response(400, "Invalid JSON")
            return

        # Check for 'data' key in JSON
        if 'data' not in data:
            self.send_error_response(400, "No data key in request")
            return

        # Send success response
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(SUCCESS_RESPONSE).encode('utf-8'))

    def send_error_response(self, status_code, message):
        self.send_response(status_code)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        error_response = {
            'status': 'error',
            'message': message
        }
        self.wfile.write(json.dumps(error_response).encode('utf-8'))

def task_func():
    return PostHandler

